<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>                    <a href="{pigcms{:U('Community/index')}">社群列表</a>|                    <a href="{pigcms{:U('Community/community_join',array('community_id'=>$_GET['community_id']))}"  class="on">{pigcms{$community_name}-群成员列表</a>                </ul>			</div>            <table class="search_table" width="100%">                <tr>                    <td style="width:60%;">                        <form action="{pigcms{:U('Community/community_join')}" method="get">                            <input type="hidden" name="c" value="Community"/>                            <input type="hidden" name="a" value="community_join"/>                            <input type="hidden" name="community_id" value="{pigcms{$_GET['community_id']}"/>                            群/用户昵称:                            <input type="text" name="comm_nickname" class="input-text" value="{pigcms{$_GET['comm_nickname']}"/>                            <input type="submit" value="查询" class="button"/>                        </form>                    </td>                </tr>            </table>						<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<style>					.table-list td{line-height:22px;padding-top:5px;padding-bottom:5px;}					</style>					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="100" align="center"/>						</colgroup>						<thead>							<tr>								<th>编号</th>                                <th>群昵称</th>                                <th>用户头像</th>                                <th>入群状态</th>                                <th>入群时候支付金额</th>                                <th>入群时间</th>							</tr>						</thead>						<tbody>							<if condition="$community_join">								<volist name="community_join" id="vo">									<tr>										<td>{pigcms{$vo.add_id}</td>                                        <td>                                            <if condition="$vo['comm_nickname']">                                                {pigcms{$vo.comm_nickname}                                                <else/>                                                {pigcms{$vo.nickname}                                            </if>                                        </td>                                        <td>                                            <img src="{pigcms{$vo.avatar}" style="width:50px;height:50px;" class="view_msg"/>                                        </td>                                        <td>                                            <if condition="$vo['add_status'] eq 1">                                                待支付                                                <elseif condition="$vo['add_status'] eq 2"/>                                                待审核                                                <elseif condition="$vo['add_status'] eq 3"/>                                                正常                                                <elseif condition="$vo['add_status'] eq 4"/>                                                已拒绝                                                <elseif condition="$vo['add_status'] eq 5"/>                                                已拒绝已退款                                                <elseif condition="$vo['add_status'] eq 6"/>                                                已拒绝退款失败                                            </if>                                        </td>                                        <td>{pigcms{$vo.charge_money}</td>                                        <td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>                                    </tr>								</volist>								<tr><td class="textcenter pagebar" colspan="11">{pigcms{$page}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="11">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>        <script>            var lockInfo = false;            function folderSwitch(folder_id, status) {                if (lockInfo) return;                lockInfo = true;                var url = '';                var close_folder = "{pigcms{:U('Community/close_folder')}";                var open_folder = "{pigcms{:U('Community/open_folder')}";                if (1 == status) {                    url = open_folder;                } else if(2 == status) {                    url = close_folder;                } else {                    return;                }                $.post(url,{'folder_id': folder_id},function(data){                    console.log(data)                    if (data && (data.status === 1 || data.status === '1')) {                        location.reload();                    } else {                        alert(data.info)                    }                },'json')                console.log('数据信息', type_id, status)                setTimeout(function(){                    lockInfo = false;                },1000);            }        </script><include file="Public:footer"/>